    {
      "id": 2,
      "claim": "Magnetotactic bacteria contain intracellular magnetite (Fe₃O₄) or greigite (Fe₃S₄) crystals called magnetosomes.",
      "evidence": "Electron microscopy and biochemical analyses have visualized chains of magnetite or greigite particles inside these cells.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Magnetite (and greigite) are ferromagnetic/ferrimagnetic materials that experience torque in an external magnetic field, aligning their magnetic dipole with the field.",
      "evidence": "Physical properties of single‑domain magnetite particles show they rotate to minimize magnetic energy; laboratory experiments demonstrate rapid alignment when a field is applied.",
      "weight": 0.25,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "The torque on magnetosomes orients the whole bacterial cell, causing it to swim along magnetic field lines (magnetotaxis).",
      "evidence": "Observations of swimming trajectories that follow Earth's magnetic field and reversal of direction when the field is reversed confirm this behavior.",
      "weight": 0.25,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Therefore the stimulus that triggers this iron‑based movement mechanism is a magnetic field (magnetism).",
      "evidence": "Only a magnetic field directly interacts with the magnetic particles; oxygen, light, and heat are sensed by separate protein‑based pathways and do not affect magnetosome alignment.",
